# Code similarity: token shingles + Jaccard over normalized token streams.
import re, keyword
def tokenize(code):
    toks = re.findall(r"[A-Za-z_][A-Za-z0-9_]*|\d+|[+\-*/=<>!&|]+", code)
    return [t if (t in keyword.kwlist or not t[0].isalpha()) else "ID" for t in toks]
def shingles(toks, n=3):
    return {" ".join(toks[i:i+n]) for i in range(len(toks)-n+1)}
snippets = {'s1': 'def add(x, y): return x + y', 's2': 'def sub(a, b): return a - b', 's3': 'print(hello)'}
q = shingles(tokenize("def add(a, b): return a + b"))
print("query tokens:", tokenize("def add(a, b): return a + b")[:12], "...")
for name, code in snippets.items():
    s = shingles(tokenize(code))
    j = len(q & s) / len(q | s) if q | s else 0.0
    print(f"  {name}: Jaccard {j:.3f}")

